ROOT = Path.cwd()
TEMPLATE_SIZE = 235727
TEMPLATE_NAME_HINT = "ВИПРАВЛЕНО"
OUTPUT = ROOT / "ПЗ Ярмоленко ІК-23 ФІНАЛ 60ст.docx"
PAYLOAD_SCRIPT = ROOT / "scripts" / "generate_thesis_word_payload.py"

W_NS = "http://schemas.openxmlformats.org/wordprocessingml/2006/main"
R_NS = "http://schemas.openxmlformats.org/officeDocument/2006/relationships"
XML_NS = "http://www.w3.org/XML/1998/namespace"

ET.register_namespace("w", W_NS)
ET.register_namespace("r", R_NS)


def qn(namespace: str, tag: str) -> str:
    return f"{{{namespace}}}{tag}"


def find_template() -> Path:
    candidates = [
        path
        for path in ROOT.glob("*.docx")
        if TEMPLATE_NAME_HINT in path.name and path.stat().st_size == TEMPLATE_SIZE
    ]
    if not candidates:
        candidates = [path for path in ROOT.glob("*.docx") if path.stat().st_size == TEMPLATE_SIZE]
    if not candidates:
        raise FileNotFoundError("Corrected thesis template was not found.")
    return candidates[0]


def load_payload_lines() -> list[str]:
    subprocess.run(["python", "-X", "utf8", str(PAYLOAD_SCRIPT)], cwd=ROOT, check=True)
    payload_path = ROOT / "scripts" / "tmp_thesis_content.txt"
    with payload_path.open("r", encoding="utf-16", newline="") as payload_file:
        text = payload_file.read()

    lines = text.replace("\r\n", "\n").replace("\r", "\n").split("\n")
    # The payload starts with a manual draft TOC. The real body begins after the
    # first page-break marker, at "ПЕРЕЛІК УМОВНИХ ПОЗНАЧЕНЬ".
    toc_break = next(i for i, line in enumerate(lines) if line == "\f")
    lines = lines[toc_break + 1 :]

    cleaned: list[str] = []
    skip_prefixes = (
        "ВСТАВИТИ",
        "ОНОВИТИ",
        "УТОЧНИТИ",
        "ПЕРЕВІРИТИ",
        "ЗНЯТИ",
        "ДОДАТИ КОРОТКУ",
    )

    for line in lines:
        stripped = line.strip()
        if stripped == "ДОДАТОК А":
            break
        if stripped.startswith("ДОДАТОК А"):
            continue
        if any(stripped.startswith(prefix) for prefix in skip_prefixes):
            continue
        if not stripped and cleaned and cleaned[-1] == "":
            continue
        cleaned.append(stripped)

    replace_references(cleaned)
    insert_expanded_sections(cleaned)
    return cleaned


