def paragraph_style_for(text: str) -> tuple[str, bool]:
    if text == "ЗМІСТ":
        return "af2", False
    if text in {
        "ПЕРЕЛІК УМОВНИХ ПОЗНАЧЕНЬ",
        "ВСТУП",
        "ВИСНОВКИ",
        "ПЕРЕЛІК ВИКОРИСТАНИХ ДЖЕРЕЛ",
    }:
        return "1", True
    if re.match(r"^\d+ [А-ЯІЇЄҐ]", text):
        return "1", True
    if text.startswith("Висновки до розділу"):
        return "2", False
    if re.match(r"^\d+\.\d+\.\d+ ", text):
        return "3", False
    if re.match(r"^\d+\.\d+ ", text):
        return "2", False
    if text.startswith("Таблиця "):
        return "a1", False
    return "a1", False


def make_paragraph(text: str, style_id: str = "a1", page_break_before: bool = False) -> ET.Element:
    paragraph = ET.Element(qn(W_NS, "p"))
    properties = ET.SubElement(paragraph, qn(W_NS, "pPr"))
    if style_id:
        style = ET.SubElement(properties, qn(W_NS, "pStyle"))
        style.set(qn(W_NS, "val"), style_id)
    if page_break_before:
        ET.SubElement(properties, qn(W_NS, "pageBreakBefore"))

    run = ET.SubElement(paragraph, qn(W_NS, "r"))
    text_element = ET.SubElement(run, qn(W_NS, "t"))
    if text.startswith(" ") or text.endswith(" "):
        text_element.set(qn(XML_NS, "space"), "preserve")
    text_element.text = text
    return paragraph


def make_page_break() -> ET.Element:
    paragraph = ET.Element(qn(W_NS, "p"))
    run = ET.SubElement(paragraph, qn(W_NS, "r"))
    br = ET.SubElement(run, qn(W_NS, "br"))
    br.set(qn(W_NS, "type"), "page")
    return paragraph


def make_table(rows: Iterable[Iterable[str]]) -> ET.Element:
    table = ET.Element(qn(W_NS, "tbl"))
    properties = ET.SubElement(table, qn(W_NS, "tblPr"))
    borders = ET.SubElement(properties, qn(W_NS, "tblBorders"))
    for border_name in ("top", "left", "bottom", "right", "insideH", "insideV"):
        border = ET.SubElement(borders, qn(W_NS, border_name))
        border.set(qn(W_NS, "val"), "single")
        border.set(qn(W_NS, "sz"), "4")
        border.set(qn(W_NS, "space"), "0")
        border.set(qn(W_NS, "color"), "000000")

    for row_index, row in enumerate(rows):
        tr = ET.SubElement(table, qn(W_NS, "tr"))
        for cell_text in row:
            tc = ET.SubElement(tr, qn(W_NS, "tc"))
            tc_pr = ET.SubElement(tc, qn(W_NS, "tcPr"))
            width = ET.SubElement(tc_pr, qn(W_NS, "tcW"))
            width.set(qn(W_NS, "w"), "2200")
            width.set(qn(W_NS, "type"), "dxa")
            paragraph = make_paragraph(cell_text, "a1")
            if row_index == 0:
                run = paragraph.find(qn(W_NS, "r"))
                if run is not None:
                    rpr = ET.Element(qn(W_NS, "rPr"))
                    ET.SubElement(rpr, qn(W_NS, "b"))
                    run.insert(0, rpr)
            tc.append(paragraph)
    return table


def read_tsv(path: Path) -> list[list[str]]:
    with path.open("r", encoding="utf-16", newline="") as table_file:
        return [line.rstrip("\r\n").split("\t") for line in table_file if line.strip()]


def content_to_elements(lines: list[str]) -> list[ET.Element]:
    gesture_rows = read_tsv(ROOT / "scripts" / "tmp_gesture_table.tsv")
    metrics_rows = read_tsv(ROOT / "scripts" / "tmp_metrics_table.tsv")
    elements: list[ET.Element] = []

    for line in lines:
        if line == "\f":
            elements.append(make_page_break())
            continue
        if line == "[[GESTURE_TABLE]]":
            elements.append(make_table(gesture_rows))
            continue
        if line == "[[METRICS_TABLE]]":
            elements.append(make_table(metrics_rows))
            continue
        if not line:
            continue

        style_id, page_break_before = paragraph_style_for(line)
        elements.append(make_paragraph(line, style_id, page_break_before))
    return elements


def build_docx() -> Path:
    template = find_template()
    shutil.copy2(template, OUTPUT)
    lines = load_payload_lines()
    new_elements = content_to_elements(lines)

    with ZipFile(OUTPUT, "r") as source:
        files = {name: source.read(name) for name in source.namelist()}

    document_root = ET.fromstring(files["word/document.xml"])
    body = document_root.find(qn(W_NS, "body"))
    if body is None:
        raise RuntimeError("word/document.xml has no body.")

    original_elements = list(body)
    front_matter = [copy.deepcopy(element) for element in original_elements[:139]]
    toc = copy.deepcopy(original_elements[139])
    main_section = copy.deepcopy(original_elements[356].find(qn(W_NS, "pPr")).find(qn(W_NS, "sectPr")))

    for element in list(body):
        body.remove(element)
    for element in front_matter:
        body.append(element)
    body.append(toc)
    body.append(make_page_break())
    for element in new_elements:
        body.append(element)
    body.append(main_section)

    files["word/document.xml"] = ET.tostring(document_root, encoding="utf-8", xml_declaration=True)

    with ZipFile(OUTPUT, "w", ZIP_DEFLATED) as target:
        for name, data in files.items():
            target.writestr(name, data)

    return OUTPUT


def main() -> None:
    output = build_docx()
    print(output)


if __name__ == "__main__":
    main()
